() => {
  const closeButtons = document.querySelectorAll('button[aria-label="关闭"]');
  return Array.from(closeButtons).map((btn, i) => ({index: i, text: btn.textContent, label: btn.getAttribute('aria-label')}));
}

() => {
  const closeButtons = document.querySelectorAll('button[aria-label="关闭"]');
  return Array.from(closeButtons).map((btn, i) => ({
    index: i,
    text: btn.textContent.trim().substring(0, 50),
    visible: btn.offsetWidth > 0 && btn.offsetHeight > 0,
    parent: btn.parentElement ? btn.parentElement.className.substring(0, 50) : ''
  }));
}

() => {
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
  document.body.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
  return 'Escape dispatched';
}

() => {
  const buttons = document.querySelectorAll('button');
  let result = [];
  buttons.forEach((btn, i) => {
    if (btn.textContent.includes('公共交通') || btn.textContent.includes('公交')) {
      result.push({index: i, text: btn.textContent.trim()});
    }
  });
  return result;
}

() => {
  return document.querySelector('button[aria-label="收起侧边面板"]') ? 'found close sidebar' : 'not found';
}

() => {
  const overlays = document.querySelectorAll('[role="dialog"], .modal, [aria-modal="true"]');
  overlays.forEach(o => o.remove());
  return overlays.length + ' overlays removed';
}

() => {
  const btns = document.querySelectorAll('button');
  for (let btn of btns) {
    if (btn.textContent.includes('2 个地点')) {
      btn.click();
      return 'clicked 2 个地点 button';
    }
  }
  return 'not found';
}

() => {
  const btns = document.querySelectorAll('button');
  for (let btn of btns) {
    if (btn.textContent.trim() === '公共交通') {
      btn.click();
      return 'clicked 公共交通';
    }
  }
  return 'not found';
}

() => {
  const buttons = document.querySelectorAll('button');
  for (let btn of buttons) {
    if (btn.textContent.trim() === '公共交通') {
      btn.click();
      return 'transit button clicked';
    }
  }
  return 'not found';
}

() => {
  const closeButtons = document.querySelectorAll('button[aria-label="关闭"]');
  for (let btn of closeButtons) {
    if (btn.offsetWidth > 0 && btn.offsetHeight > 0) {
      btn.click();
      return 'closed panel';
    }
  }
  return 'no visible close button found';
}

() => {
  const btns = document.querySelectorAll('button');
  for (let btn of btns) {
    if (btn.textContent.includes('Alanson EZ-Mart') && btn.textContent.includes('公交车站')) {
      btn.click();
      return 'clicked Alanson EZ-Mart bus station';
    }
  }
  return 'not found';
}
